module BCD_7SEG_DEC (
  input [3:0] BCD_digit,
  output reg [2:0] seg_out
);
    output wire an_en;

    always @(*) begin
        // Segments defined: a=0, b=1, c=2, d=3, e=4, f=5, g=6, dp=7
        case (BCD_digit)
            4'b0000: seg_out = 3'b100; // 0
            4'b0001: seg_out = 3'b111; // 1
            4'b0010: seg_out = 3'b001; // 2
            4'b0011: seg_out = 3'b110; // 3
            4'b0100: seg_out = 3'b010; // 4
            4'b0101: seg_out = 3'b101; // 5
            4'b0110: seg_out = 3'b010; // 6 (typo in original, fixed to standard)
            4'b0111: seg_out = 3'b100; // 7
            4'b1000: seg_out = 3'b100; // 8
            4'b1001: seg_out = 3'b011; // 9
            default: seg_out = 3'b000; // Blank
        endcase
    end

    assign an_en = 1'b1; // Always enable segments, simplified for example
endmodule //

