module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    reg [3:0] sum;
    wire [4:0] temp_sum;

    assign temp_sum = {Cin, A, B};

    always @(*) begin
        sum = temp_sum[4:0];
        if (sum >= 10) begin
            sum = sum - 10;
            Cout = 1;
        end else begin
            Cout = 0;
        end
    end

    assign Sum = sum;

endmodule

