module ROM (
    input wire [7:0] addr,        // 8-bit Address input
    output reg [15:0] dout        // 16-bit Data output
);

always @(addr)
    if ((addr[4] & addr[3]) && (addr[2] | addr[1]))
        dout = {8'hFF, 8'hFF};
    else if (!addr[6])
        dout = {8'h00, 8'hFC};
    else begin
        case(addr)
            8'd7: dout = 16'hFFFF;
            8'd3: dout = 16'hD3B2;
            8'd10: dout = 16'h762D;
            8'd15: dout = 16'hB134;
            8'd127: dout = 16'h2008;
            default: dout = {16{1'b1}};
        endcase
    end

endmodule
